/* Подключить все игры к виртуальной файловой системе. Повторный вызов
 * ничего не делает: хост можно перезапускать в одном процессе. */
static void og_project_install(void) {
    static int installed;
    if (installed) return;
    installed = 1;
    og_vfs_add_table(OG_PROJECT_FILES, OG_PROJECT_FILE_COUNT);
}

